import re
import requests

def task_func(input):
    match = re.search(r'https?://[^\s\'"<>]+', input)
    if not match:
        raise ValueError("No API endpoint found in the input string.")

    url = match.group(0)
    try:
        response = requests.get(url)
        response.raise_for_status()
        return response.json()
